    private val images: List<Pair<MatrixFrame, Long>> by lazy {
        IMAGES.map { ligne ->
            val (ms, hex) = ligne.split(':')
            MatrixFrame(IntArray(MatrixFrame.SIZE) { hex[it].digitToInt(16) * 17 }) to ms.toLong()
        }
    }

    private val v1 = VersionModele(
        id = "v1", nom = "V1",
        description = "Animation de démarrage NC MODS.",
        reglages = listOf(FONDU, PAUSE),
    ) { v ->
        // La vitesse commune divise toutes les durées : on compense pour que fondu et pause restent exacts.
        val vitesse = v.f(Personnalisation.VITESSE)
        val fonduMs = (v.f(FONDU) * 1000).roundToLong()
        val pauseMs = (v.f(PAUSE) * 1000).roundToLong()
        val premiere = images.first().first
        val pas = (fonduMs / PAS_FONDU_MS).toInt()
        val fondu = (1..pas).map { k ->
            Modele.Image(premiere.attenue(k / (pas + 1f)), (PAS_FONDU_MS * vitesse).roundToLong().coerceAtLeast(Modele.MIN_DUREE_MS))
        }
        val corps = images.map { (f, ms) -> Modele.Image(f, ms) }
        val pause = if (pauseMs >= Modele.MIN_DUREE_MS) {
            listOf(Modele.Image(MatrixFrame.blank(), (pauseMs * vitesse).roundToLong()))
        } else emptyList()
        Modele(id = "nc-mods-v2", nom = "NC MODS V2", type = Modele.Type.ANIME, images = fondu + corps + pause)
    }

    val entree = EntreeCatalogue("nc-mods-v2", "NC MODS V2", listOf(v1), categorie = "Formes")
